/**
 * Unit tests for NormalDistributionImpl#cumulativeProbability
 */
public class NormalDistributionImpl_cumulativeProbability_TriageGen2Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testCumulativeProbability_AtMean() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // At the mean, cumulative probability should be exactly 0.5
        double result = dist.cumulativeProbability(mean);
        Assert.assertEquals(0.5, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_StandardNormal() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // Test a known value: x=1 should be approx 0.841344746
        double result = dist.cumulativeProbability(1.0);
        double expected = 0.8413447460685429;
        Assert.assertEquals(expected, result, 1e-9);
    }

    @Test
    public void testCumulativeProbability_LargePositiveDeviation() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // dev = 50, which is > 40 * sd. 
        // The code returns false ? 0.0d : 1.0d (which is 1.0d)
        double result = dist.cumulativeProbability(50.0);
        Assert.assertEquals(1.0, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_LargeNegativeDeviation() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // dev = -50, which is < -40 * sd.
        // However, the code logic for branch coverage: if (abs(dev) > 40 * sd) return false ? 0 : 1
        // In the provided snippet, 'false' is a literal, so it always returns 1.0d.
        // Note: This looks like a bug in the provided source code (should check sign of dev), 
        // but I am testing the code exactly as provided.
        double result = dist.cumulativeProbability(-50.0);
        Assert.assertEquals(1.0, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_BoundaryCondition() throws MathException {
        double mean = 10.0;
        double sd = 2.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // Boundary where abs(dev) == 40 * sd
        // dev = 40 * 2 = 80. x = 10 + 80 = 90.
        double resultBoundary = dist.cumulativeProbability(90.0);

        // Since 80 is not > 80, it executes the Erf path
        double expected = 0.5 * (1.0 + org_apache_commons_math3_util_Erf_erf_proxy(80.0 / (2.0 * FastMath.sqrt(2.0))));
        // We can't call private Erf directly, so we use the logic to verify it doesn't hit the if block
        Assert.assertTrue(resultBoundary < 1.0);
    }

