    @Test
    public void testCumulativeProbability_HighPrecision() throws MathException {
        double mean = 100.0;
        double sd = 15.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // x = 115 (1 SD above mean)
        double result = dist.cumulativeProbability(115.0);
        // Z = (115-100)/15 = 1.0. P(Z<1) approx 0.841344746
        Assert.assertEquals(0.841344746, result, 1e-7);
    }
}
